      title: "模型",
      welcomeBody: "DeepSeek Harness 0.2 目前仍處於預覽階段，還有許多地方需要持續改進與精進，我們歡迎廣大開發者與使用者提供回饋與建議。新的桌面應用程式現在面向廣泛的使用者，而開發者相關的進階功能可在設定中啟用。預計 DeepSeek Harness 的產品功能與外掛 API 都會持續快速迭代、不斷演進，並逐漸趨於穩定。\n\n我們期待與全球的使用者和開發者一起，在開源、可重複使用、可組合的基礎設施之上，共同探索智慧的極限。歡迎大家用 DeepSeek Harness 將想法變成現實，並參與社群，一起豐富外掛生態系。",
