      welcomeTitle: "미리보기 안내",
      welcomeBody: "DeepSeek Harness 0.2는 아직 미리보기 단계로, 많은 부분에서 지속적인 개선과 다듬기가 필요합니다. 모든 개발자와 사용자의 피드백과 제안을 환영합니다. 새로운 데스크톱 앱은 이제 폭넓은 사용자를 대상으로 하며, 개발자 관련 고급 기능은 설정에서 사용할 수 있습니다. DeepSeek Harness의 제품 기능과 플러그인 API는 앞으로도 빠르게 반복·발전하며 점차 안정화될 예정입니다.\n\n오픈 소스이면서 재사용 가능하고 조합 가능한 인프라 위에서 전 세계 사용자와 개발자와 함께 지능의 한계를 탐구하고자 합니다. 누구나 DeepSeek Harness로 아이디어를 현실로 만들고 커뮤니티에 참여해 플러그인 생태계를 풍성하게 만들어 주시기 바랍니다.",
